import {haloIllustration} from './halo-display.js';
const $=id=>document.getElementById(id);const worker=new Worker('illustration-worker.js',{type:'module'});const photo=new Image();photo.src='pj-night.png';let ready=false,current={},request=0,cache=new Map(),lastKey='',readers=false,rotated=0,haloStrength=.3;const pendingKeys=new Map(),readersByScene={reading:false,arm:false};photo.onload=()=>{ready=true;updateIllustration(current);};photo.onerror=()=>{$('visual-status').textContent='照片暂时无法加载，请尝试阅读场景。';};
const dayPhoto=new Image();let dayReady=false;dayPhoto.onload=()=>{dayReady=true;updateIllustration(current);};dayPhoto.onerror=()=>{$('visual-status').textContent='日间照片暂时无法加载，请尝试夜间或阅读场景。';};
const armPhoto=new Image();let armReady=false;armPhoto.onload=()=>{armReady=true;updateIllustration(current);};armPhoto.onerror=()=>{$('visual-status').textContent='番石榴图片暂时无法加载，请尝试其他场景。';};
const input=document.createElement('canvas');input.width=640;input.height=360;const ctx=input.getContext('2d',{willReadFrequently:true});
function source(scene){ctx.textAlign='left';if(scene==='night'){ctx.drawImage(photo,0,0,640,360);}else if(scene==='everyday'){ctx.drawImage(dayPhoto,0,0,640,360);}else if(scene==='arm'){ctx.drawImage(armPhoto,0,0,640,360);}else{ctx.fillStyle='#eae4d8';ctx.fillRect(0,0,640,360);ctx.fillStyle='#fffaf0';ctx.fillRect(45,28,550,304);ctx.fillStyle='#b5a789';ctx.fillRect(45,28,5,304);ctx.fillStyle='#28312f';ctx.font='bold 16px sans-serif';ctx.fillText('一个宁静的早晨',78,65);ctx.font='25px sans-serif';ctx.textAlign='center';['清晨的阳光，照亮了家里的小花园。','窗外的小鸟，轻轻停在绿色的树枝上。','今天下午，我们一起到附近公园散步。'].forEach((s,i)=>ctx.fillText(s,320,118+i*43));ctx.fillStyle='#68716a';ctx.font='20px Georgia';ctx.fillText('看清细节，阅读更轻松。',320,267);ctx.font='13px sans-serif';ctx.fillText('阅读示意文字，并非视力表',320,307);}return ctx.getImageData(0,0,640,360).data;}
function paint(d){const a=new ImageData(current.topic!=='astigmatism'&&['reading','arm'].includes(current.situation)&&!readers?d.blur:d.clear,640,360),b=new ImageData(current.topic!=='astigmatism'?haloIllustration(d.clear,d.multi,haloStrength):d.multi,640,360);$('visual-a').getContext('2d').putImageData(a,0,0);$('visual-b').getContext('2d').putImageData(b,0,0);$('visual-status').textContent='';}
function diagram(which){const g=$(which==='a'?'visual-a':'visual-b').getContext('2d');g.fillStyle='#0c1d26';g.fillRect(0,0,640,360);g.fillStyle='#c6d6dd';g.font='22px system-ui';g.textAlign='center';g.fillText('可用视距 · 概念示意',320,68);g.strokeStyle='#55707c';g.lineWidth=3;g.beginPath();g.moveTo(80,220);g.lineTo(560,220);g.stroke();const labels=['远处','手臂距离','近处'];labels.forEach((v,i)=>{g.fillStyle='#dae4e8';g.font='21px system-ui';g.fillText(v,80+i*240,266);g.beginPath();g.arc(80+i*240,220,5,0,Math.PI*2);g.fill();});g.strokeStyle=which==='a'?'#9be4d2':'#f0c39d';g.lineWidth=22;g.lineCap='round';g.beginPath();g.moveTo(80,167);g.lineTo(which==='a'?95:current.lens==='enhanced'?235:320,167);g.stroke();g.font='18px system-ui';g.fillStyle='#c6d6dd';g.fillText(which==='a'?'一个主要远焦点':current.lens==='enhanced'?'增加部分中距离范围':'范围向中距离延伸',320,315);g.font='15px system-ui';g.fillText('并非实测视距或视力刻度',320,99);}
export function updateIllustration(state){if(!state?.situation)return;if(state.situation==='everyday'&&!dayPhoto.getAttribute('src'))dayPhoto.src='pj-day.png';if(state.situation==='arm'&&!armPhoto.getAttribute('src'))armPhoto.src='pj-guava.png';if(current.situation!==state.situation)readers=readersByScene[state.situation]||false;current=state;const astig=state.topic==='astigmatism',diagramMode=!astig&&state.lens!=='multi';$('halo-control').hidden=diagramMode||astig;$('rotation-control').hidden=!astig;$('alternatives').hidden=astig;$('visual').dataset.view=state.view;$('visual').dataset.diagram=String(diagramMode);$('readers-control').hidden=!['reading','arm'].includes(state.situation)||diagramMode||astig;syncGlasses(['reading','arm'].includes(state.situation)&&!diagramMode&&!astig);$('visual-a-label').textContent=diagramMode?'A · Monofocal（单焦点）':['reading','arm'].includes(state.situation)?(readers?'A · Monofocal（单焦点）＋相应度数眼镜':'A · Monofocal（单焦点）未戴眼镜'):'A · Monofocal（单焦点）示意';$('visual-b-label').textContent=diagramMode?'B · '+(state.lens==='enhanced'?'Enhanced monofocal（增强型单焦点）':state.lens==='edof'?'EDOF（延长焦深）':'Multifocal（多焦点）'):'B · Multifocal（多焦点）视觉示意';$('visual-note').textContent=diagramMode?'焦点范围概念图，不代表某款型号的性能。':'原理示意，不代表真实模糊程度或术后视力';$('visual-detail').textContent=diagramMode?'图示长度仅表达概念，并非临床测量值。':state.situation==='arm'?'番石榴按约 80 cm 目标处理。默认两侧不戴眼镜；A 可补上适合此距离的度数。':state.situation==='reading'?'同一书页，距离 40 cm。默认两侧不戴眼镜；A 可戴上阅读眼镜。':state.situation==='everyday'?'PJ 风格远景；滑杆调节光晕／雾化示意，并非术后预测。':'PJ 风格夜景；可调光晕的视觉示意，未经临床校准。实际困扰因人、型号而异。';if(astig){$('visual-a-label').textContent='A · 散光眼镜矫正';$('visual-b-label').textContent=rotated?'B · Toric（散光型）偏转 '+rotated+'°':'B · Toric（散光型）轴位对准';$('visual-note').textContent='同样的单焦点光学 · 以 1.00 D 规则散光为例';$('visual-detail').textContent=(rotated?'此偏转示例令 B 留下约 '+(2*Math.sin(rotated*Math.PI/180)).toFixed(2)+' D 残余散光。':'在理想模型中，两种矫正效果相同。')+(state.situation==='arm'?'两侧均加上理想的 80 cm 附加度数。':state.situation==='reading'?'两侧均加上理想的 40 cm 阅读附加度数。':'')+'不是个人的检查数值，也不是视力预测。';}if(diagramMode){lastKey='';diagram('a');diagram('b');$('visual-status').textContent='';return;}if((state.situation==='night'&&!ready)||(state.situation==='everyday'&&!dayReady)||(state.situation==='arm'&&!armReady)){$('visual-status').textContent='正在加载图像…';return;}const key=getKey();if(cache.has(key)){paint(cache.get(key));return;}if(lastKey===key)return;lastKey=key;$('visual-status').textContent='正在计算图像…';// Blank old images while a new situation is calculating.
for(const id of ['visual-a','visual-b']){const g=$(id).getContext('2d');g.fillStyle='#09161e';g.fillRect(0,0,640,360);}const id=++request;pendingKeys.set(id,key);worker.postMessage({id,scene:state.situation,topic:state.topic,rotated,input:source(state.situation)});}
worker.onmessage=({data:d})=>{const key=pendingKeys.get(d.id);pendingKeys.delete(d.id);if(d.id!==request)return;if(d.error){$('visual-status').textContent='图像暂时无法显示；可打开「详细说明」查看比较。';lastKey='';return;}cache.set(key,d);if(cache.size>12)cache.delete(cache.keys().next().value);if((current.topic==='astigmatism'||current.lens==='multi')&&getKey()===key)paint(d);};worker.onerror=()=>{$('visual-status').textContent='图像暂时无法显示；可打开「详细说明」查看比较。';};
$('visual-divider').oninput=()=>{$('visual').style.setProperty('--divider',$('visual-divider').value+'%');};
function syncGlasses(visible){
  $('glasses-dock').hidden=!visible;
  $('glasses-dock').dataset.on=String(readers);
  $('glasses-handle').setAttribute('aria-checked',String(readers));
  $('glasses-handle').style.removeProperty('transform');
  $('glasses-state').textContent=readers?'已戴眼镜':'已摘眼镜';
}
function wearGlasses(value){readers=value;readersByScene[current.situation]=value;updateIllustration(current);}
let glassesDrag=null;
$('glasses-handle').onpointerdown=e=>{if(e.button!==0)return;e.preventDefault();glassesDrag={y:e.clientY,on:readers};e.currentTarget.setPointerCapture(e.pointerId);};
$('glasses-handle').onpointermove=e=>{if(!glassesDrag)return;const travel=matchMedia('(orientation:landscape) and (max-height:500px)').matches?28:44;const position=Math.max(0,Math.min(travel,(glassesDrag.on?travel:0)+e.clientY-glassesDrag.y));e.currentTarget.style.transform='translateY('+position+'px)';};
$('glasses-handle').onpointerup=e=>{if(!glassesDrag)return;const dy=e.clientY-glassesDrag.y;glassesDrag=null;wearGlasses(Math.abs(dy)>12?dy>0:!readers);};
$('glasses-handle').onpointercancel=()=>{glassesDrag=null;syncGlasses(['reading','arm'].includes(current.situation)&&current.lens==='multi'&&current.topic!=='astigmatism');};
$('glasses-handle').onclick=e=>{if(e.detail===0)wearGlasses(!readers);};
$('glasses-handle').onkeydown=e=>{if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();e.stopPropagation();wearGlasses(e.key==='ArrowDown');}};

function getKey(){return (current.topic||'lens')+':'+current.situation+':'+(current.topic==='astigmatism'?String(rotated):'aligned');}
function describeRotation(value){const residual=2*Math.sin(value*Math.PI/180);$('rotation-value').textContent=(value?value+'°':'对准')+' · 残余 '+residual.toFixed(2)+' D';$('rotation-example').setAttribute('aria-valuetext',value+'度偏转，B 的残余散光 '+residual.toFixed(2)+' D');}
let rotationTimer;
$('rotation-example').oninput=()=>{const value=Number($('rotation-example').value);describeRotation(value);clearTimeout(rotationTimer);$('visual-status').textContent='正在更新散光示意…';rotationTimer=setTimeout(()=>{rotated=value;updateIllustration(current);},180);};


let haloFrame=0;
$('halo-strength').oninput=()=>{haloStrength=Number($('halo-strength').value)/100;const label=haloStrength===0?'不叠加':haloStrength<=.35?'较轻':haloStrength<=.7?'中等':'较明显';$('halo-value').textContent=label;$('halo-strength').setAttribute('aria-valuetext',label+'：仅为视觉示意');cancelAnimationFrame(haloFrame);haloFrame=requestAnimationFrame(()=>{const d=cache.get(getKey());if(d)paint(d);});};
